127	const SIZING_PROPS = new Set([
128	  'width',
129	  'height',
130	  'minWidth',
131	  'maxWidth',
132	  'minHeight',
133	  'maxHeight',
134	  'boxSize',
135	  'w',
136	  'h',
137	  'minW',
138	  'maxW',
139	  'minH',
140	  'maxH',
