1	import React from 'react';
2	import { chakra, useStyleConfig } from '@chakra-ui/react';
3	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
4	
5	const ZIMM_WISHLIST_BADGE_RECIPE = 'ZimmWishlistBadge';
6	
7	type ZimmWishlistBadgeProps = {
8	  /** Whether the current product/variant is already in the wishlist — swaps the icon between
9	   *  the outline ("Default") and solid ("Selected") states (Figma node 40000214:6159). */
10	  isSelected: boolean;
11	  isDisabled?: boolean;
12	  isLoading?: boolean;
13	  onClick?: () => void;
14	  /** Required — icon-only control, no visible text. */
15	  'aria-label': string;
16	};
17	
18	/**
19	 * Atom — the PDP wishlist toggle badge, rendered beside the product name (Figma nodes
20	 * 40003021:101731/101734). A plain native `<button>` via the chakra factory — deliberately not
21	 * Chakra's `Button`/`IconButton`, so this control has no shared styling surface with
22	 * zimmButton.css.ts's `Button` recipe (used by Add to Bag and every other button in the app)
23	 * and can't be affected by, or affect, it. `IconButton` is avoided specifically because it
24	 * hard-sets `padding: "0"` as a style prop, which would silently discard this control's 4px
25	 * padding.
26	 *
27	 * Purely presentational — size-gating, auth-gating, and the add-vs-remove decision all live in
28	 * `ProductView`; this component only renders the current state and forwards clicks.
29	 */
30	export const ZimmWishlistBadge = ({
31	  isSelected,
32	  isDisabled = false,
33	  isLoading = false,
34	  onClick,
